<script setup lang="ts">
import { computed, onMounted, ref } from 'vue';
import { Bell, Check, ChevronRight, Eye, EyeOff, Flame, Heart, Lock, LogOut, Mail, Menu, MonitorPlay, Play, Plus, Search, Sparkles, Star, X } from 'lucide-vue-next';

type Anime = { title: string; subtitle: string; genre: string; rating: string; episodes: string; image: string; progress?: number };
const featured: Anime = { title: 'Solo Leveling', subtitle: 'Arise from the shadows', genre: 'Action • Fantasy', rating: '9.4', episodes: 'Season 2', image: 'https://images.unsplash.com/photo-1531058020387-3be344556be6?auto=format&fit=crop&w=1800&q=90', progress: 62 };
const trending: Anime[] = [
  { title: 'The Apothecary Diaries', subtitle: 'Season 2', genre: 'Mystery', rating: '9.1', episodes: '24 Episodes', image: 'https://images.unsplash.com/photo-1541562232579-512a21360020?auto=format&fit=crop&w=700&q=85' },
  { title: 'Blue Lock', subtitle: 'VS. U-20 Japan', genre: 'Sports', rating: '8.8', episodes: '14 Episodes', image: 'https://images.unsplash.com/photo-1461896836934-ffe607ba8211?auto=format&fit=crop&w=700&q=85' },
  { title: 'Frieren', subtitle: 'Beyond Journey’s End', genre: 'Adventure', rating: '9.6', episodes: '28 Episodes', image: 'https://images.unsplash.com/photo-1518709594023-6eab9bab7b23?auto=format&fit=crop&w=700&q=85' },
  { title: 'Dandadan', subtitle: 'Occult Mystery', genre: 'Supernatural', rating: '8.9', episodes: '12 Episodes', image: 'https://images.unsplash.com/photo-1617791160505-6f00504e3519?auto=format&fit=crop&w=700&q=85' },
  { title: 'Kaiju No. 8', subtitle: 'Monster Sweeper', genre: 'Action', rating: '8.7', episodes: '12 Episodes', image: 'https://images.unsplash.com/photo-1519608487953-e999c86e7452?auto=format&fit=crop&w=700&q=85' }
];
const continueWatching: Anime[] = [
  { title: 'Attack on Titan', subtitle: 'The Final Chapters', genre: 'Action', rating: '9.8', episodes: 'Episode 7', image: 'https://images.unsplash.com/photo-1534447677768-be436bb09401?auto=format&fit=crop&w=800&q=85', progress: 74 },
  { title: 'Spy x Family', subtitle: 'Code: White', genre: 'Comedy', rating: '8.9', episodes: 'Episode 4', image: 'https://images.unsplash.com/photo-1511497584788-876760111969?auto=format&fit=crop&w=800&q=85', progress: 38 },
  { title: 'One Piece', subtitle: 'Egghead Arc', genre: 'Adventure', rating: '9.2', episodes: 'Episode 1122', image: 'https://images.unsplash.com/photo-1534274988757-a28bf1a57c17?auto=format&fit=crop&w=800&q=85', progress: 86 }
];
const genres = ['Action', 'Adventure', 'Comedy', 'Drama', 'Fantasy', 'Romance', 'Sci-Fi'];
const search = ref(''); const activeGenre = ref('All'); const loginOpen = ref(false); const mobileMenuOpen = ref(false); const showPassword = ref(false);
const email = ref(''); const password = ref(''); const rememberMe = ref(true); const loginError = ref(''); const profileName = ref(''); const toast = ref('');
const isLoggedIn = computed(() => Boolean(profileName.value));
const filteredTrending = computed(() => trending.filter((anime) => {
  const query = search.value.trim().toLowerCase();
  return (activeGenre.value === 'All' || anime.genre === activeGenre.value) && (!query || `${anime.title} ${anime.subtitle} ${anime.genre}`.toLowerCase().includes(query));
}));
onMounted(() => { profileName.value = localStorage.getItem('watch-anime-user') || ''; });
function notify(message: string) { toast.value = message; window.setTimeout(() => { toast.value = ''; }, 2600); }
function openLogin() { loginError.value = ''; loginOpen.value = true; mobileMenuOpen.value = false; }
function login() {
  if (!email.value.includes('@') || password.value.length < 6) { loginError.value = 'Enter a valid email and a password with at least 6 characters.'; return; }
  profileName.value = email.value.split('@')[0].replace(/[._-]/g, ' ').replace(/\b\w/g, (letter) => letter.toUpperCase());
  if (rememberMe.value) localStorage.setItem('watch-anime-user', profileName.value);
  loginOpen.value = false; password.value = ''; notify(`Welcome back, ${profileName.value}!`);
}
function logout() { localStorage.removeItem('watch-anime-user'); profileName.value = ''; notify('You have been logged out.'); }
function watch(anime: Anime) { notify(`Opening ${anime.title}…`); }
</script>

