        <nav class="hidden items-center gap-7 text-sm font-medium text-slate-300 md:flex"><a class="text-white" href="#home">Home</a><a href="#trending" class="transition hover:text-white">Trending</a><a href="#continue" class="transition hover:text-white">My List</a><a href="#genres" class="transition hover:text-white">Genres</a></nav>
        <div class="hidden items-center gap-3 md:flex">
          <label class="group flex h-10 w-52 items-center gap-2 rounded-xl border border-white/8 bg-white/5 px-3 transition focus-within:border-fuchsia-400/60"><Search class="h-4 w-4 text-slate-500 group-focus-within:text-fuchsia-300" /><input v-model="search" class="min-w-0 flex-1 bg-transparent text-sm outline-none placeholder:text-slate-500" placeholder="Search anime" /></label>
          <button class="grid h-10 w-10 place-items-center rounded-xl text-slate-300 transition hover:bg-white/8 hover:text-white" @click="notify('No new notifications.')"><Bell class="h-4 w-4" /></button>
          <button v-if="!isLoggedIn" class="rounded-xl bg-white px-4 py-2.5 text-sm font-bold text-slate-950 transition hover:bg-fuchsia-100" @click="openLogin">Log in</button>
          <div v-else class="flex items-center gap-2"><button class="flex items-center gap-2 rounded-xl bg-white/8 py-2 pl-2 pr-3 text-sm font-semibold" @click="notify('Profile settings are coming soon.')"><span class="grid h-7 w-7 place-items-center rounded-lg bg-gradient-to-br from-violet-500 to-fuchsia-500 text-xs">{{ profileName.charAt(0) }}</span>{{ profileName }}</button><button class="p-2 text-slate-400 hover:text-white" title="Log out" @click="logout"><LogOut class="h-4 w-4" /></button></div>
        </div>
        <button class="grid h-10 w-10 place-items-center rounded-xl bg-white/6 md:hidden" @click="mobileMenuOpen = !mobileMenuOpen"><X v-if="mobileMenuOpen" class="h-5 w-5" /><Menu v-else class="h-5 w-5" /></button>
      </div>
      <div v-if="mobileMenuOpen" class="border-t border-white/8 bg-[#0d101b] px-5 py-4 md:hidden"><div class="flex flex-col gap-4 text-sm text-slate-300"><a href="#trending" @click="mobileMenuOpen = false">Trending</a><a href="#continue" @click="mobileMenuOpen = false">My List</a><button v-if="!isLoggedIn" class="w-fit rounded-lg bg-white px-4 py-2 font-bold text-slate-950" @click="openLogin">Log in</button><button v-else class="w-fit text-left text-fuchsia-300" @click="logout">Log out</button></div></div>
    </header>

    <section id="home" class="relative mx-auto max-w-7xl px-5 pb-14 pt-8 lg:px-8 lg:pt-12">
      <div class="absolute inset-x-0 top-0 h-[460px] overflow-hidden rounded-b-[3rem]"><img :src="featured.image" class="h-full w-full object-cover opacity-45" alt="Featured anime backdrop" /><div class="absolute inset-0 bg-gradient-to-r from-[#080a12] via-[#080a12]/65 to-[#080a12]/20"></div><div class="absolute inset-0 bg-gradient-to-t from-[#080a12] via-transparent"></div></div>
      <div class="relative grid min-h-[410px] items-end gap-8 pb-5 lg:grid-cols-[1fr_290px]">
        <div class="max-w-2xl"><div class="mb-4 inline-flex items-center gap-2 rounded-full border border-fuchsia-400/25 bg-fuchsia-500/10 px-3 py-1.5 text-xs font-semibold text-fuchsia-200"><Sparkles class="h-3.5 w-3.5" /> #1 in Japan today</div><p class="mb-3 text-sm font-medium text-slate-300">{{ featured.genre }} <span class="mx-2 text-slate-600">•</span> {{ featured.episodes }}</p><h1 class="font-display text-5xl font-bold leading-none tracking-tight sm:text-7xl">{{ featured.title }}</h1><p class="mt-5 max-w-xl text-sm leading-6 text-slate-300 sm:text-base">The world’s weakest hunter discovers a mysterious system that gives him the power to level up beyond anyone’s imagination.</p><div class="mt-7 flex flex-wrap gap-3"><button class="inline-flex items-center gap-2 rounded-xl bg-white px-5 py-3 text-sm font-bold text-slate-950 transition hover:scale-[1.02]" @click="watch(featured)"><Play class="h-4 w-4 fill-slate-950" /> Watch episode 1</button><button class="inline-flex items-center gap-2 rounded-xl border border-white/15 bg-white/8 px-5 py-3 text-sm font-semibold transition hover:bg-white/15" @click="notify('Added Solo Leveling to your list.')"><Plus class="h-4 w-4" /> My list</button></div></div>
        <div class="hidden rounded-2xl border border-white/10 bg-[#111521]/70 p-4 backdrop-blur lg:block"><div class="mb-3 flex items-center justify-between text-xs text-slate-400"><span>Continue watching</span><span>{{ featured.progress }}%</span></div><div class="relative aspect-video overflow-hidden rounded-xl"><img :src="featured.image" class="h-full w-full object-cover" alt="Solo Leveling" /><button class="absolute inset-0 grid place-items-center bg-slate-950/20" @click="watch(featured)"><span class="grid h-11 w-11 place-items-center rounded-full bg-white text-slate-900"><Play class="ml-0.5 h-4 w-4 fill-current" /></span></button></div><div class="mt-3 h-1.5 overflow-hidden rounded-full bg-white/10"><div class="h-full rounded-full bg-fuchsia-500" :style="{ width: `${featured.progress}%` }"></div></div></div>
      </div>
    </section>

