    <section id="trending" class="mx-auto max-w-7xl px-5 py-14 lg:px-8"><div class="mb-6 flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><p class="mb-1 text-xs font-bold uppercase tracking-[.18em] text-fuchsia-400">New this week</p><h2 class="font-display text-3xl font-bold">Trending now</h2></div><label class="flex h-10 items-center gap-2 rounded-xl border border-white/8 bg-white/5 px-3 sm:hidden"><Search class="h-4 w-4 text-slate-500" /><input v-model="search" class="w-full bg-transparent text-sm outline-none placeholder:text-slate-500" placeholder="Search anime" /></label></div><div v-if="filteredTrending.length" class="grid grid-cols-2 gap-4 sm:grid-cols-3 lg:grid-cols-5"><article v-for="(anime, index) in filteredTrending" :key="anime.title" class="group cursor-pointer" @click="watch(anime)"><div class="relative aspect-[3/4] overflow-hidden rounded-2xl bg-white/5"><img :src="anime.image" :alt="anime.title" class="h-full w-full object-cover transition duration-500 group-hover:scale-110" /><div class="absolute inset-x-0 bottom-0 h-1/2 bg-gradient-to-t from-[#080a12] to-transparent"></div><span class="absolute left-3 top-3 grid h-7 w-7 place-items-center rounded-lg bg-fuchsia-500 text-xs font-black">{{ index + 1 }}</span><button class="absolute bottom-3 right-3 grid h-9 w-9 place-items-center rounded-full bg-white text-slate-950 opacity-0 shadow-lg transition group-hover:opacity-100"><Play class="ml-0.5 h-3.5 w-3.5 fill-current" /></button></div><h3 class="mt-3 truncate font-semibold">{{ anime.title }}</h3><div class="mt-1 flex items-center gap-2 text-xs text-slate-400"><span>{{ anime.genre }}</span><span class="flex items-center gap-1 text-amber-300"><Star class="h-3 w-3 fill-current" />{{ anime.rating }}</span></div></article></div><div v-else class="rounded-2xl border border-dashed border-white/15 px-6 py-16 text-center text-slate-400">No shows match “{{ search }}”. Try another title.</div></section>

