    <Transition name="fade"><div v-if="toast" class="fixed bottom-5 left-1/2 z-50 -translate-x-1/2 rounded-xl border border-white/15 bg-[#1c2030] px-4 py-3 text-sm font-medium shadow-2xl shadow-black/40"><Check class="mr-2 inline h-4 w-4 text-emerald-400" />{{ toast }}</div></Transition>
